INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Sicherheitsrichtlinien nur für IT-Mitarbeiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gelten für alle Mitarbeiter"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Sicherheitsrichtlinien?', 3, '[{"text": "Sicherheitsverhalten fördern", "correct": true, "because": "Regeln für Mitarbeiter"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Sicherheitsrichtlinien?', 5, '[{"text": "Passwortrichtlinien", "correct": true, "because": "Sichern Zugänge"}, {"text": "Nutzungsregeln", "correct": true, "because": "Definieren Verhalten"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sicherheitsrichtlinien schützen vor Fehlern. b) Sie sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht in vielen Organisationen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Sicherheitsrichtlinien?', 4, '[{"text": "Passwortanforderungen", "correct": false, "because": "Kern der Richtlinien"}, {"text": "Nutzungsverbote", "correct": false, "because": "Schützen Systeme"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Sicherheitsrichtlinien auch physische Regeln umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Zutrittsregeln"}, {"text": "Nein", "correct": false, "because": "Umfassender Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regel ist typisch für Sicherheitsrichtlinien?', 3, '[{"text": "Mindestpasswortlänge", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Verhaltensfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche decken Sicherheitsrichtlinien ab?', 5, '[{"text": "Gerätenutzung", "correct": true, "because": "Regelt Umgang"}, {"text": "Datenhandling", "correct": true, "because": "Schützt Informationen"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Sicherheitsrichtlinien reduzieren Risiken. b) Sie betreffen nur Führungskräfte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Mitarbeiter betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Sicherheitsrichtlinien?', 4, '[{"text": "Verhaltensregeln", "correct": false, "because": "Kern der Richtlinien"}, {"text": "Sanktionen", "correct": false, "because": "Durchsetzung sichern"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Sicherheitsrichtlinien nur technisch?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Regeln"}, {"text": "Ja", "correct": false, "because": "Verhalten inklusive"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zu Sicherheitsrichtlinien?', 4, '[{"text": "USB-Nutzungsverbot", "correct": true, "because": "Schützt vor Malware"}, {"text": "Passwortwechsel", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Kein Verhaltensfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Sicherheitsrichtlinien optional sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Pflicht in vielen Firmen"}, {"text": "Ja", "correct": false, "because": "Sicherheit gewährleisten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Sicherheitsrichtlinien?', 3, '[{"text": "Klarheit der Regeln", "correct": true, "because": "Verständnis fördern"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Gründlichkeit zählt"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Passwortrichtlinien sind Teil davon. b) Sie betreffen nur IT-Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch physische Regeln"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regeln verbessern die Sicherheit?', 5, '[{"text": "Verbot privater Geräte", "correct": true, "because": "Reduziert Risiken"}, {"text": "Regelmäßige Passwortänderung", "correct": true, "because": "Schützt Zugänge"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Sicherheitsrichtlinien unwichtig?', 3, '[{"text": "Durchsetzung", "correct": false, "because": "Sichert Einhaltung"}, {"text": "Schulungen", "correct": false, "because": "Fördern Bewusstsein"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Sicherheitsrichtlinien nur für Technik?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Verhalten und Prozesse"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Sicherheitsrichtlinien regelmäßig überprüft werden sollten?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassung an Bedrohungen"}, {"text": "Nein", "correct": false, "because": "Aktualisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für Sicherheitsrichtlinien?', 4, '[{"text": "Passwortkomplexität", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
